package glitch

import data.glitch_lib

unencrypted_protocols := {"http://", "ftp://", "telnet://", "smtp://", "tcp://"}
unencrypted_ports := {80, 21, 23, 25}
encryption_flags := {"ssl_enabled", "enable_ssl", "use_tls", "require_encryption", "encrypt", "enable_https_only", "force_ssl", "validate_certs"}
false_like_strings := {"no", "false", "0", "off"}

check_unencrypted_protocol(node) {
    node.ir_type == "String"
    regex.match("(?i)^(http://|ftp://|telnet://|smtp://|tcp://)", node.value)
} else {
    node.ir_type == "String"
    regex.match("(?i).*://", node.value)
    not regex.match("(?i)^https://", node.value)
    not regex.match("(?i)^ftps://", node.value)
    not regex.match("(?i)^ssl://", node.value)
    not regex.match("(?i)^tls://", node.value)
}

check_encryption_flag(node) {
    node.ir_type == "Boolean"
    node.value == false
} else {
    node.ir_type == "String"
    node.value in false_like_strings
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for unencrypted protocols in attribute values
    check_unencrypted_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted protocol used in configuration. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for encryption flags set to false
    attr.name in encryption_flags
    check_encryption_flag(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption flag disabled. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all variables in the parent
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check for unencrypted protocols in variable values
    check_unencrypted_protocol(var.value)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Unencrypted protocol in variable. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all variables in the parent
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check for encryption flags set to false in variables
    var.name in encryption_flags
    check_encryption_flag(var.value)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption flag disabled in variable. (CWE-319)"
    }
}

